/** once per old per-build media cache: what still hashes to a current file moves into the stable cache, the rest goes */
async function adopt(name) {
  const old = await caches.open(name), cache = await caches.open(MEDIA_CACHE);
  for (const req of await old.keys()) {
    try {
      const key = mediaKey(new URL(req.url));
      if (!key || await cache.match(key)) continue;
      const res = await old.match(req);
      if (!res || res.status !== 200) continue;
      const buf = await res.arrayBuffer();
      if (key.slice(-12) !== await sha12(buf)) continue;      // changed since: it comes fresh on its next use
      await cache.put(key, new Response(buf, { status: 200, statusText: 'OK', headers: res.headers }));
    } catch { /* one entry never stops the rest */ }
  }
}
/** drop the media keys no current file has (an old hash, a removed file) */
async function prune() {
  const cache = await caches.open(MEDIA_CACHE);
  for (const req of await cache.keys()) {
    const u = new URL(req.url), v = u.searchParams.get('__v');
    if (v && mediaKey(u) !== u.origin + u.pathname + '?__v=' + v) await cache.delete(req);
  }
}

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((k) => k.startsWith('koala-shell-') && k !== SHELL_CACHE).map((k) => caches.delete(k)));
    await self.clients.claim();
    for (const k of keys.filter((k) => k.startsWith('koala-media-') && k !== MEDIA_CACHE)) {
      try { await adopt(k); } catch { /* adopted what it could */ }
      await caches.delete(k);
    }
    try { await prune(); } catch { /* next activate */ }
  })());
});

/** a byte range of a whole cached response (a <video> asks for ranges; iOS Safari will not play a 200 answer) */
async function ranged(req, res) {
  const m = /^bytes=(\d*)-(\d*)$/.exec(req.headers.get('range') || '');
  if (!m || (!m[1] && !m[2])) return res;
  const buf = await res.arrayBuffer(), size = buf.byteLength;
  const start = m[1] ? Number(m[1]) : Math.max(0, size - Number(m[2]));
  const end = m[1] && m[2] ? Math.min(Number(m[2]), size - 1) : size - 1;
  if (start >= size || start > end) return new Response(null, { status: 416, headers: { 'Content-Range': 'bytes */' + size } });
  return new Response(buf.slice(start, end + 1), { status: 206, statusText: 'Partial Content', headers: {
    'Content-Type': res.headers.get('Content-Type') || 'application/octet-stream', 'Content-Range': 'bytes ' + start + '-' + end + '/' + size,
    'Content-Length': String(end - start + 1), 'Accept-Ranges': 'bytes' } });
}

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return; // cross-origin (font CDNs etc.) stays network-only

  if (req.mode === 'navigate') {
    // network-first: an online visitor always gets the latest shell; offline falls back to what was cached
    event.respondWith((async () => {
      try {
        const fresh = await fetch(req);
        (await caches.open(SHELL_CACHE)).put(req, fresh.clone());
        return fresh;
      } catch {
        const cache = await caches.open(SHELL_CACHE);
        return (await cache.match(req)) ?? (await cache.match('./index.html')) ?? Response.error();
      }
    })());
    return;
  }

  // the rooms (panoramas + room.json) are re-rendered under the same names: network-first, so a new panorama never
  // pairs with an old camera (that drew the board in the wrong place); the cache is only the offline fallback.
  // Every .json too: the clip/voice indexes grow under the same name (a cached koala/index.json kept new Hebrew
  // lip-sync clips unplayed — he spoke with his mouth closed)
  if (url.pathname.includes('/env/') || url.pathname.endsWith('.json')) {
    event.respondWith((async () => {
      const cache = await caches.open(MEDIA_CACHE);
      try { const fresh = await fetch(req); if (fresh.ok && fresh.status === 200) cache.put(req, fresh.clone()); return fresh; }
      catch { return (await cache.match(req)) ?? Response.error(); }
    })());
    return;
  }
  // the build's own hashed JS/CSS: this build's shell cache (stale-while-revalidate; a new build has new names)
  if (/\.(js|css)$/.test(url.pathname)) {
    event.respondWith((async () => {
      const cache = await caches.open(SHELL_CACHE);
      const cached = await cache.match(req);
      const network = fetch(req).then((res) => { if (res.ok && res.status === 200) cache.put(req, res.clone()).catch(() => undefined); return res; }).catch(() => undefined);
      return cached ?? (await network) ?? Response.error();
    })());
    return;
  }
  if (/\.(webp|png|jpg|jpeg|mp4|m4a|woff2|glb)$/.test(url.pathname)) {
    const key = mediaKey(url);
    event.respondWith((async () => {
      const cache = await caches.open(MEDIA_CACHE);
      if (key) {
        // content-addressed: a hit IS the current file — served from the cache, no revalidation download
        const hit = await cache.match(key);
        if (hit) return req.headers.has('range') ? ranged(req, hit) : hit;
        const res = await fetch(req);
        if (res.ok && res.status === 200) cache.put(key, res.clone()).catch(() => undefined);
        return res;
      }
      // not in the build's list (a file added after it): stale-while-revalidate under its plain URL
      const cached = await cache.match(req);
      const network = fetch(req).then((res) => { if (res.ok && res.status === 200) cache.put(req, res.clone()).catch(() => undefined); return res; }).catch(() => undefined);
      if (cached) return req.headers.has('range') ? ranged(req, cached) : cached;
      return (await network) ?? Response.error();
    })());
  }
});
